def valid_palindrome_length(N, K):
    even_possible = N % 3 == 0 or (K > N // 2 and N % 3 != 1)
    odd_possible = N % 3 == 1 or (K > (N // 2) - 1 and N % 3 == 2)
    return even_possible or odd_possible

def compute_mod(n, mod):
    if n == 1:
        return 1
    base = 1
    result = 1
    while n > 0:
        if n % 2 == 1:
            result = (result * base) % mod
        base = (base * base) % mod
        n //= 2
    return result

def count_sequences(N, K):
    if N == 1:
        return 1
    if K == 1:
        return 0
    if valid_palindrome_length(N, K):
        return (compute_mod(N, 1000000007) + 1) % 1000000007
    else:
        return 0

