import sys

def get_sequences(matrix):
    n = len(matrix)
    sequences = [[[], set()] for _ in range(n)]

    for i, row in enumerate(matrix):
        for j, value in enumerate(row):
            for sequence in sequences[i]:
                if sequence[1] & (1 << (j + 1)):
                    sequences[i][0].append((sequence[0] + [j + 1], sequence[1]|(1 << (j + 1))))
                if sequence[1] & (1 << i + 1):
                    sequences[i][0].append((sequence[0], sequence[1]|(1 << i + 1)))

    return list(filter(lambda seq: len(seq[0]) >= n, sequences[n]))[0][0]

def shortest_crimp_string(p, matrix, string):
    sequence = get_sequences([row[:] for row in matrix])
    min_length = float('inf')
    for characters, flag in sequence:
        reversed_string = reversed(string)
        for i, prob in enumerate(matrix):
            if (1 << i + 1) & flag or sum(prob[j] for j in characters) != sum(prob[j] for j in reversed_string):
                break
        else:
            min_length = min(min_length, len(string) - len(chars) + len(set(reversed_string)))
    return min_length

