def psearch(p, s, t):
    idx = ord('a')  # Initialize variable to calculate actual indices
    n = len(t)
    m = len(s)

    # Initialize dictionaries for indices and positions
    indices = {chr(i): i-ord('a') for i in range(97, 100)}
    positions = {i: -1 for i in range(1, 27)}

    ans = ['0']  # Initialize answer with 0
    count = 0  # Count current length of subarray

    # Construct dictionary from input
    for i, ki in enumerate(p):
        indices[chr((indices[ki] + i) % 26 + ord('a'))] = i
        positions[i] = indices[ki]

    def check(jj, s, t):
        # Check if substring t matches s
        return jj >= m and count >= m and positions[jj] == m and all(p[i] == j for i, j in zip(t, s))

    # Calculate indices of each char in t after p
    dic = []
    for i in range(1, 27):
        dic.append(set())
        for j in range(0, n):
            if t[j] == chr((ord(char[j] + i) % 26 + ord('a'))): dic[i].add(j)

    # Start with first character and check
    check(positions[s[0]], s, t)
    if not check(positions[s[0]], s, t): 
        return ' '.join(ans)

    pr = 0  # Record preindex
    for j in range(1, n):
        fchar = positions[s[j]] - positions[s[j - 1]]
        if fchar > 0:
            for i in range(1, 27):
                if dic[i][pr] < fchar:
                    break
                if i == 26:
                    return ' '.join(ans)
                count += fchar
                pr = dic[i][pr]
                for char2 in dic[i]:
                    if check(char2 * (i - 1) + chr((indices[char2 + i] + j) % 26 + ord('a')), s[i:], t):
                        return ' '.join(ans)
    return ' '.join(ans)


