def is_double_rainbow(start: int, end: int, color: int) -> bool:
    sequence = [start]
    color_map = set()
    color_map.add(seq[-2][1], seq[-1][1])
    i = 0
    while sequence[-1] != end:
        prev_color = color_map[i] if i < c else None
        for pair in graph[sequence[-1]]:
