import random as rd

def make_random_binary(m, n):
    """
    Make a list of 1's and -1's with length n, so that the parity of
    each "element" is m. If m==0, then the output is just random.

    """
    out = [0]*n
    for i in range(1, n-1):
        if sum(out[::2]+out[1::2]) >= m:
            out[i] = 1
    return out

def number_of_extinction(df, b, k):
    n = len(df[0])
    probs = [1]*n
    for i, x in enumerate(df):
        for p, c in enumerate(x):
            n0, n1 = min(n-k, n-i), 0
            k0, k1 = n-k-(df[i+k0][p].count('1')), df[i+k0][p].count('1')
            for i in range(n0, k+1):
                j = min(n1, n-1-i)
                f = (1 if df[k1][p][:i].count('1') > 0 else 0)
                jnew = j - (f+k1-j)**2 + n - i - (f+k1-j) if f else 0 
                probs[i] += probs[j] - probs[jnew] + rd.random()
                if probs[i] < 1.0e-20:
                    return i
    return n-1

def run():
    import sys
    arr = list(map(int, sys.stdin.readline().strip().split()))
    n, q = arr[0], arr[1]
    df = {}
    for i in range(n):
        a = list(map(str, sys.stdin.readline().strip().split()))
        df[i] = make_random_binary(ord(a[2])-ord('a'), len(a[0]))
        df[i] = make_random_binary(ord(a[2])-ord('a'), len(a[0])+1)

    for i in range(q):
        arr = list(map(int, sys.stdin.readline().strip().split()))
        l, r, k = arr[0], arr[1], arr[2]
        while True:
            cur = number_of_extinction(df, l, k)
            if cur >= r:
                rmin = l
                l = cur
                if l == k:
                    rmin = k
                q = rmin - (l-1) + 1
                continue
            df[l+k] = [
                (c, df[i+k][p][c] if i+k > r else df[i+k][p].count('1'))
                for p, c in enumerate(df[l][2])
                ]
            l += 1
        print(q)
