import sys

def compute_reachable_states(s, t):
    seq1 = len(set(s))
    seq2 = len(set(t))

    if seq1 == seq2:
        return len(set(s) & set(t))
    if seq1 == 1:
        return len(set(s) ^ set(t))
    if seq2 == 1:
        return len(set(s) | set(t))
    if seq1 <= 2:
        return len(set(s) | set(t))
    if seq2 <= 2:
        return len(set(s) ^ set(t))
    return len(set(s) | set(t))

