from collections import defaultdict

def thief_solution(n, k, costs):
    # Map to store the distinct total costs of the thief's knapsack
    knapsack_costs = defaultdict(int)
    knapsack_costs[0] = 0  # Base case: no products stolen

    # Iterate through all possible combinations of k products
    for i in range(1, n + 1):
        for comb in combinations(range(n), i):
            total_cost = sum([k * cost for k, cost in zip(comb, costs)])
            knapsack_costs[total_cost] = knapsack_costs.get(total_cost, 0) + 1

    # Convert the results into a sorted list and print
    total_costs = sorted(knapsack_costs.keys())
    print(*total_costs, sep=' ')  # Use Standard Output Format


# Function to generate all combinations of indices in a range
def combinations(range_start, n):
    if n < 0: 
        return
    elif n == 0:
        yield []
    else:
        for i in range(range_start, 0, -1):
            for e in combinations(i - 1, n - 1):
                yield [i - 1] + e


