def is_perfect_power(n):
    """Check if the given number is a perfect power of any integer k."""
    if n < 2:
        return False
    for b in range(2, math.log(n, 2) + 1):
        a = round(n ** (1.0 / (b + 1)))
        if a ** (b + 1) == n:
            return True
    return False

def closest_perfect_power(n):
    """Find the closest perfect power to n."""
    for b in range(1, 15):  # Assuming b+1 is at most 14
        for a in range(2, int(n ** (1.0 / (b + 1))) + 1):
            x = a ** (b + 1)
            if x <= n:
                return x
            if x > n:
                break
    return n  # If no perfect power within the range is found

