def solve_sequence(sequence, N, K):
    """
    Solves the problem of making the sequence orderly with minimum swaps.
    """
    count = 0
    i = 0
    visited = set()

    while i < N - 1 and len(visited) < K:
        if sequence[i] != sequence[i + 1]:
            count += 1
            for j in range(i + 1, N):
                if sequence[j] == sequence[i]:
