from heapq import heappush, heappop

def solve(k, n, *costs):
    """
    Given the number of kinds of products and the number of products to take, find all possible total costs
    of stolen products. The costs of products are represented by a list of integers.
    """
    costs.sort()  # Sort the costs to make the solution processable
    total_costs = set()

    def calculate_cost(index, remaining_products):
        if sum(costs[index:]) > remaining_products:
            return 0
        if index == len(costs) - 1:
            return costs[-1] * (remaining_products // (n - 1)) + remaining_products % (n - 1)
        return costs[index] * (remaining_products // (n - 1)) + remaining_products % (n - 1)

    product_count = [0] * n
    visited = set()

    def backtrack(index, remaining_products, cost_so_far):
        if remaining_products == 0:
            visit(calculate_cost(index, remaining_products))
            return
        for i in range(index, n):
            if cost_so_far + costs[i] in visited:
                continue
            if sum(costs[i:]) > remaining_products // (n - 1) or remaining_products % (n - 1) != 0:
                visited.add(cost_so_far + costs[i])
                backtrack(i, remaining_products - 1 - (n - 2) * (sum(costs[i:]) // (n - 1)), cost_so_far + costs[i])
                visited.remove(cost_so_far + costs[i])

    def visit(total_cost):
        total_costs.add(total_cost)

    for i in range(k, n - k):
        product_count[i] = 1
        visit(calculate_cost(i, k))

    product_count[0] = k
    visit(calculate_cost(0, k))

    product_count[n - k] = k

    for i in range(k):
        product_count[n - k - (n - 2) * (k - 1) - i] = 1
        visit(calculate_cost(n - k - (n - 2) * (k - 1) - i, k))

    product_count[n - k] = k

    # Iterative using bottom-up to avoid re-creation of the heap per (i, cost_so_far) visit.
    for last_product_count in range(k, n - k - 1, -1):
        heappush(total_costs, heappop(total_costs) + calculate_cost(last_product_count, k))

    for last_product_count in range(n - k - 1, -1, -1):
        heappush(total_costs, heappop(total_costs) + calculate_cost(last_product_count, k))

    return '\n'.join(map(str, sorted(total_costs)))


