import random
from fractions import Fraction

def expected_value(x, k, p):
    # Base case: if k is 1, the expected value is 1 if x is odd, and p / (100 - p) if x is even
    if k == 1:
        if x % 2 == 0:
            return Fraction(p / (100 - p), 1)
        else:
            return 1

    # Recursive case: calculate the expected value for k-1 and then adjust based on the current value of x
    expected = p / (100 - p) / ((x + 1) - 1 if x % 2 == 0 else x - 1)
    for _ in range(k-1):
        expected *= Fraction(2, 100) if random.randint(1, 100) <= p else Fraction(1, 100)
    return expected

