def minimum_moves(A, K):
    incoming = [0] * len(A)
    for i in range(len(A) - 1):
        if i + 2 * K <= len(A):
            incoming[i + 2 * K] = max(incoming[i + 2 * K], A[i] - A[i + 1] + 1)
        if i + K <= len(A):
            incoming[i + K] = max(incoming[i + K], A[i + 1] - A[i] + 1)
        if i + K - 1 <= len(A):
            incoming[i + K - 1] = max(incoming[i + K - 1], A[i + K - 1] - A[i + K] + 1)
    masked = [0] * len(A)
