    def matrix_col(i, j, n):
        return f"{matrix_row(i, j, n)} {matrix_row(j, i, n)}"

    for i in range(n):
        dp[to_index(initial_string[i])][to_index(initial_string[i])] = 0

    for i in range(n):
        for j in range(n):
            for k in range(n):
                if dp[i][j] + matrix_row(j, k, n) < dp[i][k]:
                    dp[i][k] = dp[i][j] + matrix_row(j, k, n)
                if dp[j][k] + matrix_col(j, k, n) < dp[i][k]:
                    dp[i][k] = dp[j][k] + matrix_col(j, k, n)

    for i in range(n):
        best = min(dp[i])
        if best >= n:
            return 0
    return n - best

