    def __init__(self, n, x=-1):
        self.bitMask = 1 << 20
        self.bitCount = collections.defaultdict(int)
        self.bitSet = set()
        self.bitMask = self.bitMask - 1
        self.bitSet.add(x)
        self.bitVal = 1
        self.index = 0

    def add(self, value):
        if value >= self.bitMask:
            value %= self.bitMask
        mask = 1 << self.index
        if value >= mask:
            self.index += 1
            value -= mask
        if value != self.bitVal:
            self.bitVal = value
            self.bitSet.add(value)

        self.bitCount[value] += 1
        self.index += 1

    def remove(self, value):
        if value == 0:
            self.index -= 1
            return self.bitVal
        if self.bitVal != value:
            self.bitVal = value
            self.index -= 1
        self.bitCount[value] -= 1
        value -= (1 << self.index)
        if self.bitCount[value] == 0:
            self.bitSet.remove(value)
        return self.bitVal


