    closest = 0
    min_diff = float('inf')
    for b in range(int(log(n, 2)), 0, -2):
        a = round(n ** (1 / (b + 1)))
        if a > 1:
            x = a ** (b + 1)
            diff = abs(n - x)
            if diff < min_diff:
                min_diff = diff
                closest = x
            elif diff == min_diff:
                closest = min(closest, x)
    return closest

