def orderly_subsequence_length(sequence, k):
    count = {}
    minimum = None
    for value in set(sequence):
        count[value] = sequence.count(value)
        if minimum is None or count[value] < minimum:
            minimum = count[value]
    if minimum > 1:
        return -1 # Impossible to make orderly subsequence with length at least k
    return sum(min(count[i], k - 1) for i in count) - (k - minimum) # Calculate minimum moves required to align neighboring elements

